import{_ as a,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-05-18","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-05-18","date":"2021-05-18T00:00:00.000Z","updated":"2021-05-19T00:00:00.000Z","tags":["Ceph","Orchestrator","Self","adm Agent","Reconciliation Loop","Push Model","Architecture Improvement"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-18.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-18.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-05-18.md"};function i(n,e,s,h,c,p){return t(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-本周的-orchestrator-会议" tabindex="-1">会议主题：本周的 orchestrator 会议 <a class="header-anchor" href="#会议主题-本周的-orchestrator-会议" aria-label="Permalink to &quot;会议主题：本周的 orchestrator 会议&quot;">​</a></h4><h4 id="参会人员-全体成员" tabindex="-1">参会人员：全体成员 <a class="header-anchor" href="#参会人员-全体成员" aria-label="Permalink to &quot;参会人员：全体成员&quot;">​</a></h4><h4 id="会议日期-2021-05-18" tabindex="-1">会议日期：2021-05-18 <a class="header-anchor" href="#会议日期-2021-05-18" aria-label="Permalink to &quot;会议日期：2021-05-18&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>主要议题</strong>：</p><ul><li>探讨 self-adm agent 的功能和必要性。</li><li>讨论 cephadm 中的 reconciliation loop 的扩展性和性能问题。</li><li>评估是否需要改进架构以支持更快的故障转移。</li></ul></li><li><p><strong>讨论细节</strong>：</p><ul><li><strong>self-adm agent</strong>：会议重点讨论了 self-adm agent 的潜在收益和架构影响，包括是否需要实施该代理及其对架构的影响。</li><li><strong>reconciliation loop</strong>：讨论了当前 cephadm 中 reconciliation loop 的扩展性限制，特别是在创建 SSH 连接和执行远程命令时的性能问题。</li><li><strong>架构改进</strong>：会议讨论了如何改进架构以支持更快的故障转移，包括考虑使用 push 模型而不是 pull 模型，以及如何处理潜在的竞争条件和失败模式。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>确认改进 reconciliation loop 和引入 self-adm agent 的必要性。</li><li>初步决定采用 push 模型，通过 agent 向 manager 推送信息，以提高性能和响应速度。</li><li>需要进一步明确 agent 的责任和具体实施细节。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>分配任务给特定人员以细化 self-adm agent 的实施细节。</li><li>开始设计和实现 agent 的 push 模型，确保其与现有系统的兼容性和安全性。</li><li>考虑长期目标，减少对 SSH 的依赖，并探索如何简化 manager 的架构。</li></ul></li><li><p><strong>其他讨论点</strong>：</p><ul><li>讨论了如何处理升级路径和兼容性问题。</li><li>探讨了 manager 模块的架构重构可能性，但认为这是一个长期目标。</li></ul></li></ol><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在接近预定时间结束，未有其他紧急议题需要讨论。</li><li>全体成员祝大家有一个愉快的周末。</li></ul><p>本次会议重点在于优化 Ceph 的 orchestration 功能，特别是通过引入新的 self-adm agent 来解决现有的性能瓶颈问题。会议强调了详细的实施计划和考虑潜在的架构影响的重要性，并确定了后续的行动计划。</p>',9)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
